import React from 'react';

/**
 * Simple button component for testing basic extraction
 */
export interface SimpleButtonProps {
  /** Button variant */
  variant?: 'primary' | 'secondary';
  /** Button content */
  children: React.ReactNode;
  /** Click handler */
  onClick?: () => void;
}

export const SimpleButton: React.FC<SimpleButtonProps> = ({
  variant = 'primary',
  children,
  onClick
}) => {
  return (
    <button
      className={`btn btn--${variant}`}
      onClick={onClick}
    >
      {children}
    </button>
  );
};

export default SimpleButton;

import React from 'react';

/**
 * Complex card component for testing advanced extraction patterns
 */
export interface ComplexCardProps {
  /** Card variant with multiple options */
  variant?: 'default' | 'outlined' | 'filled' | 'elevated';
  /** Card size */
  size?: 'sm' | 'md' | 'lg' | 'xl';
  /** Whether card is interactive */
  interactive?: boolean;
  /** Custom styling */
  className?: string;
  /** Card content */
  children: React.ReactNode;
  /** Optional header slot */
  header?: React.ReactNode;
  /** Optional footer slot */
  footer?: React.ReactNode;
  /** Optional actions */
  actions?: Array<{
    label: string;
    onClick: () => void;
    variant?: 'primary' | 'secondary';
  }>;
  /** Loading state */
  loading?: boolean;
  /** Disabled state */
  disabled?: boolean;
  /** Click handler for interactive cards */
  onClick?: () => void;
  /** Additional data attributes */
  'data-testid'?: string;
}

export const ComplexCard: React.FC<ComplexCardProps> = ({
  variant = 'default',
  size = 'md',
  interactive = false,
  className = '',
  children,
  header,
  footer,
  actions,
  loading = false,
  disabled = false,
  onClick,
  'data-testid': testId,
  ...props
}) => {
  const baseClasses = 'card';
  const variantClasses = {
    default: 'card--default',
    outlined: 'card--outlined',
    filled: 'card--filled',
    elevated: 'card--elevated'
  };

  const sizeClasses = {
    sm: 'card--sm',
    md: 'card--md',
    lg: 'card--lg',
    xl: 'card--xl'
  };

  const combinedClassName = [
    baseClasses,
    variantClasses[variant],
    sizeClasses[size],
    interactive && 'card--interactive',
    loading && 'card--loading',
    disabled && 'card--disabled',
    className
  ].filter(Boolean).join(' ');

  return (
    <div
      className={combinedClassName}
      onClick={interactive && !disabled ? onClick : undefined}
      data-testid={testId}
      {...props}
    >
      {header && (
        <div className="card__header">
          {header}
        </div>
      )}

      <div className="card__content">
        {loading ? (
          <div className="card__loading">Loading...</div>
        ) : (
          children
        )}
      </div>

      {actions && actions.length > 0 && (
        <div className="card__actions">
          {actions.map((action, index) => (
            <button
              key={index}
              className={`btn btn--${action.variant || 'secondary'}`}
              onClick={action.onClick}
              disabled={disabled}
            >
              {action.label}
            </button>
          ))}
        </div>
      )}

      {footer && (
        <div className="card__footer">
          {footer}
        </div>
      )}
    </div>
  );
};

export default ComplexCard;

import React from 'react';

// Component with edge cases that might break parsing
export interface ProblematicComponentProps {
  // Dynamic prop types
  [key: string]: any;
  // Required props
  id: string;
  // Union with complex types
  variant?: 'a' | 'b' | 'c' | string;
  // Function prop with complex signature
  onComplexEvent?: (data: { id: string; value: any }, meta?: Record<string, unknown>) => Promise<void>;
  // Generic prop
  data?: Record<string, any>;
  // Computed prop with default
  computed?: string;
}

// Arrow function component with destructuring
export const ProblematicComponent = ({
  id,
  variant = 'a',
  onComplexEvent,
  data = {},
  computed = `computed-${Date.now()}`,
  ...restProps
}: ProblematicComponentProps) => {
  // Complex logic that might confuse parsers
  const derivedValue = React.useMemo(() => {
    return Object.keys(data).length > 0 ? 'has-data' : 'no-data';
  }, [data]);

  return (
    <div 
      id={id}
      className={`problematic problematic--${variant} problematic--${derivedValue}`}
      {...restProps}
    >
      <span>{computed}</span>
      {data && Object.keys(data).map(key => (
        <div key={key}>{key}: {String(data[key])}</div>
      ))}
    </div>
  );
};

// Class component for testing different patterns
export class ClassComponent extends React.Component<{ title: string; children?: React.ReactNode }> {
  render() {
    const { title, children } = this.props;
    return (
      <div className="class-component">
        <h1>{title}</h1>
        {children}
      </div>
    );
  }
}

// Component with no explicit props interface
export const NoPropsInterface = (props: any) => {
  return <div {...props}>No explicit props</div>;
};

// Higher-order component
export const withHOC = <P extends object>(Component: React.ComponentType<P>) => {
  return (props: P) => <Component {...props} />;
};

export default ProblematicComponent;

